// ─── File: ArchDemo.java ───
// Runnable demo contrasting SOA vs microservices for the SAME transfer flow.
// Each class would be its own file in a real project.
package com.bank.arch;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ArchDemo {
    private static final Logger log = Logger.getLogger(ArchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TransferRequest req = new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000"));

        log.info("===== SOA style: central ESB + shared DB + central governance =====");
        SharedDatabase sharedDb = new SharedDatabase();
        EnterpriseServiceBus esb = new EnterpriseServiceBus(sharedDb);
        esb.route(req);     // everything flows through the smart central bus

        log.info("===== Microservices style: direct + per-service DB + events =====");
        EventBus eventBus = new EventBus();
        FraudService fraud = new FraudService(new PerServiceStore("fraud-db"), eventBus);
        TransferService transfer = new TransferService(new PerServiceStore("transfer-db"), fraud, eventBus);
        eventBus.subscribe("TransferCompleted", e -> log.info("  [async] Notification svc reacts to " + e));
        transfer.transfer(req);  // smart endpoints, dumb pipes; owns its own data
    }
}

// ─── model/TransferRequest.java ───
class TransferRequest {
    final String from, to; final BigDecimal amount;
        TransferRequest(String from, String to, BigDecimal amount) { this.from = from;
        this.to = to
        this.amount = amount; }
    public String toString() { return from + "→" + to + " Rs." + amount; }
}

// ─── soa/SharedDatabase.java ───
// One enterprise database shared by all SOA services (coupling point).
class SharedDatabase {
    private static final Logger log = Logger.getLogger(SharedDatabase.class.getName());
    void write(String table, String data) { log.fine("SHARED DB write " + table + ": " + data); }
}

// ─── soa/EnterpriseServiceBus.java ───
// The SMART central bus: routing, transformation, orchestration. Also a bottleneck/SPOF.
class EnterpriseServiceBus {
    private static final Logger log = Logger.getLogger(EnterpriseServiceBus.class.getName());
    private final SharedDatabase db;
    EnterpriseServiceBus(SharedDatabase db) { this.db = db; }
    void route(TransferRequest req) {
        log.info("ESB: received " + req + " (SOAP). Routing + transforming centrally.");
        // ESB orchestrates both coarse-grained services, both on the SHARED db
        log.info("ESB → FraudService.check (coarse-grained, shared schema)");
        db.write("FRAUD_CHECKS", req.toString());
        log.info("ESB → PaymentService.debitCredit (coarse-grained, shared schema)");
        db.write("ACCOUNTS", "debit " + req.from + " credit " + req.to);
        log.info("ESB: done. Central governance; services deploy together.");
    }
}

// ─── micro/PerServiceStore.java ───
// Each microservice owns its OWN private datastore. No sharing.
class PerServiceStore {
    private static final Logger log = Logger.getLogger(PerServiceStore.class.getName());
    private final String name;
    PerServiceStore(String name) { this.name = name; }
    void write(String data) { log.fine("[" + name + "] private write: " + data); }
}

// ─── micro/EventBus.java ───
// Lightweight async messaging (dumb pipe). Replaces the smart ESB.
class EventBus {
    private final Map<String, List<java.util.function.Consumer<String>>> subs = new HashMap<>();
    void subscribe(String event, java.util.function.Consumer<String> handler) {
        subs.computeIfAbsent(event, k -> new ArrayList<>()).add(handler);
    }
    void publish(String event, String payload) {
        subs.getOrDefault(event, List.of()).forEach(h -> h.accept(payload));
    }
}

// ─── micro/FraudService.java ───
// Fine-grained, owns its own data, deployable independently.
class FraudService {
    private static final Logger log = Logger.getLogger(FraudService.class.getName());
    private final PerServiceStore store; private final EventBus bus;
        FraudService(PerServiceStore store, EventBus bus) { this.store = store;
        this.bus = bus; }
    boolean check(TransferRequest req) {
        store.write("fraud score for " + req);           // its OWN database
        boolean ok = req.amount.compareTo(new BigDecimal("1000000")) < 0;
        log.info("FraudService (fine-grained, own DB): " + (ok ? "PASS" : "BLOCK"));
        return ok;
    }
}

// ─── micro/TransferService.java ───
// Calls fraud directly (smart endpoint), owns its data, emits an event (dumb pipe).
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final PerServiceStore store; private final FraudService fraud; private final EventBus bus;
    TransferService(PerServiceStore store, FraudService fraud, EventBus bus) {
            this.store = store;
            this.fraud = fraud
            this.bus = bus;
    }
    void transfer(TransferRequest req) {
        log.info("TransferService: received " + req + " (REST, lightweight).");
        if (!fraud.check(req)) { log.severe("blocked by fraud"); return; }   // direct call, no ESB
        store.write("debit " + req.from + " credit " + req.to);              // its OWN database
        log.info("TransferService: completed; deploys independently; decentralized governance.");
        bus.publish("TransferCompleted", req.toString());                    // async event, dumb pipe
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
